def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    own = []
    opp = []
    for pair in history:
        own.append(pair[0])
        opp.append(pair[1])

    total_d = 0
    for a in opp:
        if a == 'D':
            total_d += 1
    total_def_rate = total_d / float(n)

    rlen = 10 if n >= 10 else n
    recent_d = 0
    start = n - rlen
    for i in range(start, n):
        if opp[i] == 'D':
            recent_d += 1
    recent_def_rate = recent_d / float(rlen)

    run_o_D = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            run_o_D += 1
        else:
            break

    run_o_C = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C':
            run_o_C += 1
        else:
            break

    run_both_D = 0
    for i in range(n - 1, -1, -1):
        if own[i] == 'D' and opp[i] == 'D':
            run_both_D += 1
        else:
            break

    mutual_cc_run = 0
    for i in range(n - 1, -1, -1):
        if own[i] == 'C' and opp[i] == 'C':
            mutual_cc_run += 1
        else:
            break

    if opp[-1] == 'D':
        idx = n - 1 - run_o_D
        mutual_before = 0
        if idx >= 0:
            for i in range(idx, -1, -1):
                if own[i] == 'C' and opp[i] == 'C':
                    mutual_before += 1
                else:
                    break
    else:
        mutual_before = mutual_cc_run

    c_tot = 0
    c_d = 0
    d_tot = 0
    d_d = 0

    for i in range(n - 1):
        mine = own[i]
        nxt = opp[i + 1]
        if mine == 'C':
            c_tot += 1
            if nxt == 'D':
                c_d += 1
        else:
            d_tot += 1
            if nxt == 'D':
                d_d += 1

    if c_tot == 0:
        p0 = 0.18
    else:
        p0 = (c_d + 0.10) / float(c_tot + 0.60)

    if d_tot == 0:
        p1 = 0.68
    else:
        p1 = (d_d + 0.12) / float(d_tot + 0.60)

    last_a = own[-1]
    last_o = opp[-1]

    if last_a == 'C':
        q = p0
    else:
        q = p1

    if last_o == 'D':
        if run_o_D >= 2 and q < 0.60:
            q = 0.60
        elif q > 0.45:
            q = 0.45
        if run_o_D >= 4:
            q = max(q, 0.74)
        if run_o_D >= 6:
            q = max(q, 0.85)
    else:
        if run_o_C >= 3 and q > 0.30:
            q = 0.30

    if recent_def_rate >= 0.70:
        q = max(q, 0.80)
    if total_def_rate >= 0.78:
        q = max(q, 0.85)

    if d_tot >= 1 and d_d == 0 and recent_def_rate <= 0.10 and mutual_cc_run >= 5:
        return 'D'

    if d_tot >= 2 and (d_tot - d_d) >= 2 and recent_def_rate <= 0.25:
        return 'D'

    if p1 <= 0.30 and d_tot >= 1 and recent_def_rate <= 0.15:
        return 'D'

    if q >= 0.74 or recent_def_rate >= 0.72 or total_def_rate >= 0.72:
        if (
            last_a == 'D' and last_o == 'D'
            and run_o_D <= 3
            and p0 <= 0.30
            and mutual_before >= 8
            and rng.random() < 0.25
        ):
            return 'C'
        return 'D'

    if last_a == 'D' and last_o == 'D':
        if p0 <= 0.32 and recent_def_rate <= 0.50 and run_o_D <= 3 and mutual_before >= 6:
            if rng.random() < 0.70:
                return 'C'
        elif p0 <= 0.20 and recent_def_rate <= 0.65 and run_o_D == 4 and mutual_before >= 10:
            if rng.random() < 0.25:
                return 'C'
        return 'D'

    if last_a == 'C' and last_o == 'D':
        if run_o_D == 1 and mutual_before >= 8 and recent_def_rate <= 0.15:
            return 'C'
        if run_o_D == 2 and mutual_before >= 8 and recent_def_rate <= 0.20:
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        if run_o_D >= 3:
            return 'D'
        return 'D'

    if last_o == 'C':
        if p1 <= 0.45 and d_tot >= 1 and recent_def_rate <= 0.20:
            return 'D'
        if last_a == 'D' and last_o == 'C' and p1 <= 0.50 and rng.random() < 0.65:
            return 'D'

        if mutual_cc_run >= 12 and recent_def_rate == 0.0 and total_def_rate <= 0.05:
            if n % 17 == 0 and rng.random() < 0.22:
                return 'D'
            if rng.random() < 0.02:
                return 'D'

        return 'C'

    if q >= 0.52:
        return 'D'

    return 'C'
